input.command:
cd /tmp && node -e "
const sharp = require('sharp');
const src = '/Users/lixing/WorkRep/TodoList/craft-projects/x-ant-design/capture/screenshot-1440.png';
(async () => {
  // top nav full width
  await sharp(src).extract({left:0, top:0, width:1440, height:64}).toFile('/tmp/crops/01-nav.png');
  // left sidebar
  await sharp(src).extract({left:0, top:64, width:240, height:600}).toFile('/tmp/crops/02-sidebar.png');
  // hero + toc
  await sharp(src).extract({left:240, top:64, width:1200, height:300}).toFile('/tmp/crops/03-hero.png');
})();
console.log('done');
"

