const sharp = require('sharp');
const src = '/Users/lixing/WorkRep/TodoList/craft-projects/x-ant-design/capture/screenshot-1440.png';
(async () => {
  // Detect white card bounds inside preview. Extract preview region (block7 y511 h383 x348 w926)
  const region = {left:348, top:511, width:926, height:383};
  const { data, info } = await sharp(src).extract(region).raw().toBuffer({resolveWithObject:true});
  const ch=info.channels, W=info.width,H=info.height;
  const isWhite=(x,y)=>{const i=(y*W+x)*ch;return data[i]>248&&data[i+1]>248&&data[i+2]>248;};
  const isGray=(x,y)=>{const i=(y*W+x)*ch;return Math.abs(data[i]-240)<8&&Math.abs(data[i+1]-242)<8&&Math.abs(data[i+2]-245)<8;};
  // scan a middle row for transitions
  const scanRow=(y)=>{
    let runs=[];let cur=null;
    for(let x=0;x<W;x++){const w=isWhite(x,y);if(w!==cur){runs.push([x,w?'white':'other']);cur=w;}}
    return runs;
  };
  console.log('row 200:', JSON.stringify(scanRow(200)));
  // vertical scan at x=400 for top/bottom of card
  const scanCol=(x)=>{let runs=[];let cur=null;for(let y=0;y<H;y++){const w=isWhite(x,y);if(w!==cur){runs.push([y,w?'white':'other']);cur=w;}}return runs;};
  console.log('col 400:', JSON.stringify(scanCol(400)));
})();
"

