.sem-block {
  margin-bottom: 48px;
}

.sem-preview {
  padding: 24px;
  background: #fafafa;
  border: 1px solid rgba(5, 5, 5, 0.06);
  border-radius: 8px;
  overflow-x: auto;
}

.sem-table {
  margin-top: 16px;
  overflow-x: auto;
}

.sem-table table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

.sem-table td {
  padding: 12px 16px;
  border-bottom: 1px solid rgba(5, 5, 5, 0.06);
  vertical-align: top;
  color: rgba(0, 0, 0, 0.88);
}

.sem-table .sem-key {
  font-family: SFMono-Regular, Consolas, 'Liberation Mono', Menlo, Courier, monospace;
  white-space: nowrap;
  width: 160px;
}

