input.content:
.token-table {
  margin-bottom: 48px;
}

.tok-section {
  margin-bottom: 24px;
}

.tok-header {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: pointer;
  font-size: 16px;
}

.tok-arrow {
  display: inline-flex;
  color: rgba(0, 0, 0, 0.45);
  transition: transform 0.2s;
}
.tok-arrow.open {
  transform: rotate(90deg);
}

.tok-section-title {
  font-weight: 500;
  color: rgba(0, 0, 0, 0.88);
}

.tok-hint {
  font-size: 13px;
  color: #1677ff;
}

.tok-tablewrap {
  margin-top: 16px;
  overflow-x: auto;
}

.tok-tablewrap table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

.tok-tablewrap th,
.tok-tablewrap td {
  padding: 12px 16px;
  text-align: left;
  vertical-align: top;
  border-bottom: 1px solid rgba(5, 5, 5, 0.06);
  font-weight: 400;
  color: rgba(0, 0, 0, 0.88);
}

.tok-tablewrap th {
  font-weight: 500;
  background: #fafafa;
  white-space: nowrap;
}

.tok-name {
  font-family: SFMono-Regular, Consolas, 'Liberation Mono', Menlo, Courier, monospace;
  white-space: nowrap;
}

.tok-type {
  font-family: SFMono-Regular, Consolas, 'Liberation Mono', Menlo, Courier, monospace;
  font-size: 13px;
  color: #c41d7f;
}

.tok-default {
  font-family: SFMono-Regular, Consolas, 'Liberation Mono', Menlo, Courier, monospace;
  font-size: 13px;
  white-space: nowrap;
}

.tok-dot {
  display: inline-block;
  width: 12px;
  height: 12px;
  margin-right: 8px;
  border: 1px solid rgba(5, 5, 5, 0.15);
  border-radius: 50%;
  vertical-align: middle;
}

@media (max-width: 575px) {
  .tok-tablewrap th,
  .tok-tablewrap td {
    padding: 10px 12px;
  }
}

