node -e '
for (const r of ["docs-react-introduce-cn","docs-spec-introduce-cn"]) {
 const c=require("./capture/routes/"+r+"/capture.json");
 const o=c.outline||[];
 console.log("===== "+r+" SIDE =====");
 o.filter(e=>e.tag==="a" && e.box && e.box.x<270 && e.box.y>80)
  .sort((a,b)=>a.box.y-b.box.y)
  .forEach(e=>console.log(e.box.y, JSON.stringify(e.text), e.font));
}
'

