/* ---- install command card ---- */
.install-card {
  margin: 16px 0 24px;
  border: 1px solid rgba(5, 5, 5, 0.06);
  border-radius: 8px;
  overflow: hidden;
  background: #ffffff;
}

.install-tabs {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 12px 0;
  border-bottom: 1px solid rgba(5, 5, 5, 0.06);
}

.install-tab {
  padding: 8px 14px;
  border: 0;
  background: transparent;
  font-size: 14px;
  color: rgba(0, 0, 0, 0.65);
  cursor: pointer;
  border-radius: 6px 6px 0 0;
}
.install-tab.static {
  cursor: default;
}
.install-tab.active {
  color: #1677ff;
  font-weight: 500;
  box-shadow: inset 0 -2px 0 #1677ff;
