toolUseResult.originalFile:
:root {
  --x-font-family: -apple-system, 'system-ui', 'Segoe UI', Roboto, 'Helvetica Neue',
    Arial, 'Noto Sans', sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji',
    'Segoe UI Symbol', 'Noto Color Emoji';
  --x-font-mono: SFMono-Regular, Consolas, 'Liberation Mono', Menlo, Courier,
    monospace;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--x-font-family);
  font-size: 14px;
  line-height: 1.5715;
  color: rgba(0, 0, 0, 0.88);
  background: #ffffff;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#root {
  min-height: 100vh;
}

a {
  color: #1677ff;
  text-decoration: none;
  background-color: transparent;
}

a:hover {
  color: #4096ff;
}

code,
kbd,
pre,
samp {
  font-family: var(--x-font-mono);
}

/* Thin scrollbars used by the side menus */
.x-scroll::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
.x-scroll::-webkit-scrollbar-thumb {
  background: rgba(0, 0, 0, 0.12);
  border-radius: 3px;
}
.x-scroll::-webkit-scrollbar-track {
  background: transparent;
}

/* prevent the whole doc frame from scrolling sideways on small screens */
html,
body {
  overflow-x: hidden;
}

/* ---- page typography ---- */
.page-h1 {
  margin: 0 0 20px;
  font-size: 32px;
  line-height: 1.35;
  font-weight: 600;
  color: rgba(0, 0, 0, 0.88);
}

.page-h2 {
  margin: 56px 0 24px;
  font-size: 24px;
  line-height: 1.35;
  font-weight: 500;
  color: rgba(0, 0, 0, 0.88);
}

.page-h3 {
  margin: 40px 0 16px;
  font-size: 18px;
  line-height: 1.4;
  font-weight: 500;
  color: rgba(0, 0, 0, 0.88);
}

.page-list {
  margin: 0 0 8px;
  padding-left: 24px;
  color: rgba(0, 0, 0, 0.88);
}
.page-list li {
  margin-bottom: 8px;
}

.api-link-line {
  color: rgba(0, 0, 0, 0.88);
}

/* anchor offset for the wrapped demo sections */
.demo-anchor {
  scroll-margin-top: 88px;
}

/* ---- inline code & code blocks (doc prose) ---- */
.ic {
  padding: 0.2em 0.4em;
  margin: 0;
  font-family: var(--x-font-mono);
  font-size: 0.85em;
  background: rgba(0, 0, 0, 0.06);
  border-radius: 6px;
}

.codeblock {
  margin: 0;
  padding: 16px 24px;
  font-family: var(--x-font-mono);
  font-size: 13px;
  line-height: 1.6;
  color: rgba(0, 0, 0, 0.88);
  background: #f6f8fa;
  border-radius: 8px;
  overflow-x: auto;
}
.codeblock .ln {
  color: rgba(0, 0, 0, 0.35);
  user-select: none;
}

.doc-prose p {
  color: rgba(0, 0, 0, 0.88);
}

/* small "edit" pencil next to the article title */
.title-edit {
  color: rgba(0, 0, 0, 0.45);
  margin-left: 8px;
  vertical-align: middle;
}

