// figure titles sit in article column x ~ 300-1140, centered, often bold 14-16
o.filter(e=>e.box && e.box.y>950 && e.text && e.text.length<40)
 .sort((a,b)=>a.box.y-b.box.y)
 .filter((e,i,arr)=> i===0 || e.box.y-arr[i-1].box.y>60 || e.text!==arr[i-1].text)
 .forEach(e=>{
   if(/特征|如何进行|范式|演进|GUI|AGI|时代|应用|推行者|材料|指印|RICH/.test(e.text))
   console.log(e.box.y, e.font, JSON.stringify(e.text));
 });
' | head -40

