input.content:
.site-footer {
  margin-top: 64px;
  padding: 56px 0 32px;
  background: #f0f2f5;
}

.sf-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.sf-col {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.sf-title {
  font-size: 14px;
  font-weight: 500;
  color: rgba(0, 0, 0, 0.88);
  margin-bottom: 4px;
}

.sf-link {
  font-size: 13px;
  color: rgba(0, 0, 0, 0.65);
}
.sf-link:hover {
  color: #1677ff;
}

.sf-bottom {
  margin-top: 40px;
  text-align: center;
  font-size: 13px;
  color: rgba(0, 0, 0, 0.45);
}

@media (max-width: 1199px) {
  .sf-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 575px) {
  .sf-grid {
    grid-template-columns: 1fr;
  }
}

