input.command:
node -e '
const fs=require("fs");
const raw=fs.readFileSync("capture/capture.json","utf8");
// find context around each haspopup / aria-expanded
["haspopup","aria-expanded"].forEach(k=>{
  let i=raw.indexOf(k),n=0;
  while(i>=0&&n<8){console.log(k,"=>",JSON.stringify(raw.slice(Math.max(0,i-120),i+60)));i=raw.indexOf(k,i+1);n++;}
});
'

