input.content:
.dm-details {
  position: relative;
  display: inline-block;
}

.dm-summary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  list-style: none;
  cursor: pointer;
}
.dm-summary::-webkit-details-marker {
  display: none;
}

.dm-panel {
  position: absolute;
  top: calc(100% + 6px);
  z-index: 1100;
  min-width: 140px;
  max-height: 320px;
  padding: 4px;
  background: #ffffff;
  border-radius: 8px;
  box-shadow:
    0 6px 16px 0 rgba(0, 0, 0, 0.08),
    0 3px 6px -4px rgba(0, 0, 0, 0.12),
    0 9px 28px 8px rgba(0, 0, 0, 0.05);
  overflow-y: auto;
}
.dm-details.right .dm-panel {
  right: 0;
}
.dm-details.left .dm-panel {
  left: 0;
}

.dm-item {
  padding: 8px 12px;
  font-size: 14px;
  color: rgba(0, 0, 0, 0.88);
  border-radius: 6px;
  cursor: pointer;
}
.dm-item:hover {
  background: rgba(0, 0, 0, 0.04);
}
.dm-item.selected {
  font-weight: 500;
  color: #1677ff;
  background: #e6f4ff;
}

